get_ipython().run_cell_magic('writefile', 'All_intents.py', '\nimport os\nimport re\nimport io\nimport email\nimport time\nimport json\nimport torch\nimport shutil\nimport imaplib\nimport smtplib\nimport tempfile\nimport pandas as pd\nimport fitz  \nfrom PIL import Image\nfrom bs4 import BeautifulSoup\nfrom datetime import datetime, timedelta\nfrom email.header import decode_header\nfrom email.mime.text import MIMEText\nfrom hijri_converter import Hijri\nfrom langchain.docstore.document import Document\nfrom langchain.embeddings import HuggingFaceEmbeddings\nfrom langchain.vectorstores import FAISS\nfrom langchain.text_splitter import RecursiveCharacterTextSplitter\nfrom langchain.retrievers import BM25Retriever, ParentDocumentRetriever\nfrom langchain.storage import InMemoryStore\nfrom transformers import AutoTokenizer, AutoModelForCausalLM, pipeline\nfrom googleapiclient.discovery import build\nfrom google.oauth2 import service_account\nfrom ArabicOcr import arabicocr  \nimport gc  \nimport openpyxl  \nimport json\nimport re\nfrom datetime import datetime, timedelta\nfrom hijri_converter import Hijri, Gregorian\nfrom googleapiclient.discovery import build\nfrom google.oauth2 import service_account\nimport json\nimport re\nimport re\n\nfrom config import tokenizer, llm_pipeline, DEVICE, SERVICE_ACCOUNT_FILE, SCOPES\nfrom RulesForIntents import RULES_DIR , load_intent_rules , deduce_administrative_rule , update_intent_rules_file  \n')


