get_ipython().run_cell_magic('writefile', '-a All_intents.py', 'def handle_hr_procedures(email_body, sender_info):\n    """\n    نسخة نصية مباشرة (No-JSON): للموارد البشرية.\n    تم تحديثها لتعطي أولوية قصوى للقواعد المتعلمة.\n    """\n    # تحميل القواعد المكتسبة\n    learned_rules = load_intent_rules("HR")\n    \n    # طباعة للتحقق من أن القواعد تم تحميلها فعلاً (Debug)\n    if learned_rules:\n        print(f"✅ [HR] تم تحميل قواعد متعلمة: {learned_rules[:5000]}...")\n    else:\n        print("ℹ️ [HR] لا توجد قواعد متعلمة، سيتم استخدام القواعد الافتراضية.")\n\n    system_prompt = f"""\nأنت مسؤول في قسم الإشراف. مهمتك الرد على طلبات الموظفين أو إحالتها لإدارات أخرى.\n\n### ⚠️ تعليمات صارمة جداً (القواعد المتعلمة):\nيجب عليك تطبيق القواعد التالية وتفضيلها على أي معرفة سابقة لديك. هذه القواعد تم استنتاجها من توجيهات المدير السابقة وهي ملزمة:\n--------------------------------------------------\n{learned_rules if learned_rules else "لا توجد قواعد خاصة حالياً، طبق لوائح العمل القياسية."}\n--------------------------------------------------\n\nالهيكلية الإلزامية للرد:\n1. المنصب والكنية مثلا : سعادة مدير , المهندس محمد , السيد ..\n2. البسملة والتحية الرسمية\n3. نص الرد (مبني حصراً على القواعد أعلاه).\n4. الختام بـ: "وتقبلوا تحياتي، مدير قسم الإشراف".\n\nتنبيه: لا تقم أبداً بتأليف معلومات غير موجودة، ولا تستخدم الأقواس للشرح.\n"""\n\n    prompt = f"المرسل: {sender_info}\\nالطلب: {email_body}\\n\\nصغ الرد الرسمي مباشرة بناءً على التعليمات أعلاه:"\n\n    messages = [\n        {"role": "system", "content": system_prompt},\n        {"role": "user", "content": prompt}\n    ]\n\n    try:\n        text_input = tokenizer.apply_chat_template(messages, tokenize=False, add_generation_prompt=True, enable_thinking=False)\n        \n        # رفعنا التوكنز قليلاً لأن الرد قد يكون مفصلاً\n        outputs = llm_pipeline(text_input, max_new_tokens=1024, temperature=0.1)\n        \n        response_text = outputs[0][\'generated_text\'].replace(text_input, "").strip()\n        \n        # تنظيف أي شوائب قد يضيفها النموذج\n        response_text = response_text.replace(\'```\', \'\').strip()\n        \n        return response_text\n\n    except Exception as e:\n        print(f"⚠ خطأ في معالجة الموارد البشرية (Text-Mode): {e}")\n        return None\n')


